"use client";
import { type Classification, type VisionAnalysis } from "@/types/api";
import React, { useState, useRef, useEffect } from "react";
import { Upload, ImageIcon, Scan, CheckCircle2, ShieldAlert, Loader2, Activity, Sparkles, Cpu, X } from "lucide-react";
import { useActiveCyclone } from "@/hooks/useActiveCyclone";
import { useDataSource } from "@/hooks/useDataSource";
import { getApiBaseUrl } from "@/lib/api";

const unavailableClassification = (): Classification => ({
  is_cyclone: null, category: "Classification unavailable", category_short: "UNAVAILABLE",
  confidence: null, dvorak_t: null, wind_speed_knots: null,
  checkpoint_status: "BACKEND_UNAVAILABLE", is_trained_weights: false,
  scientifically_validated: false, is_reliable: false, operational_status: "UNAVAILABLE", probabilities: {}
});
const unavailableVision: VisionAnalysis = {
  status: "ANALYSIS_UNAVAILABLE", scientifically_validated: false,
  category: "Not independently validated", dvorak_t_number: null, estimated_knots: null,
  eye_characterization: "Not verified", convective_signature: "Not verified", recommended_actions: []
};

export default function ClassificationPage() {
  const { selectedCycloneId, selectedCycloneName } = useActiveCyclone();
  const { getSourceBadge } = useDataSource();
  const sourceBadge = getSourceBadge();
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [geminiLoading, setGeminiLoading] = useState(false);
  const [result, setResult] = useState<Classification | null>(null);
  const [geminiResult, setGeminiResult] = useState<VisionAnalysis | null>(null);
  const [selectedFrame, setSelectedFrame] = useState<number | null>(null);
  const analysisController = useRef<AbortController | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const selectedFile = e.target.files[0];
      setPreviewUrl(URL.createObjectURL(selectedFile));
      setResult(null);
      setGeminiResult(null);
      setSelectedFrame(null);
      await analyzeImage(selectedFile);
    }
  };

  async function analyzeImage(imageFile: File) {
    analysisController.current?.abort();
    const controller = new AbortController();
    analysisController.current = controller;
    const timer = setTimeout(() => controller.abort(), 65000);
    setAnalyzing(true);
    setGeminiLoading(false);
    setGeminiResult(unavailableVision);
    try {
      if (imageFile.size > 5 * 1024 * 1024 || !['image/png', 'image/jpeg'].includes(imageFile.type)) {
        throw new Error('Unsupported image');
      }
      const formData = new FormData();
      formData.append('file', imageFile);
      const response = await fetch(`${getApiBaseUrl()}/api/classify`, {
        method: 'POST', body: formData, signal: controller.signal
      });
      if (!response.ok) throw new Error('Classification unavailable');
      const data = await response.json();
      if (!data?.prediction || typeof data.prediction.category !== 'string' ||
          !(data.prediction.confidence === null || (typeof data.prediction.confidence === 'number' &&
            Number.isFinite(data.prediction.confidence) && data.prediction.confidence >= 0 && data.prediction.confidence <= 100))) {
        throw new Error('Invalid classification response');
      }
      if (analysisController.current === controller) setResult(data.prediction);
    } catch {
      if (analysisController.current === controller) setResult(unavailableClassification());
    } finally {
      clearTimeout(timer);
      if (analysisController.current === controller) setAnalyzing(false);
    }
  }

  useEffect(() => () => analysisController.current?.abort(), []);
  useEffect(() => () => { if (previewUrl?.startsWith('blob:')) URL.revokeObjectURL(previewUrl); }, [previewUrl]);

  useEffect(() => {
    const handleGlobalPaste = async (e: ClipboardEvent) => {
      if (e.clipboardData && e.clipboardData.files && e.clipboardData.files.length > 0) {
        const pastedFile = e.clipboardData.files[0];
        if (pastedFile.type.startsWith("image/")) {
          setPreviewUrl(URL.createObjectURL(pastedFile));
          setResult(null);
          setGeminiResult(null);
          setSelectedFrame(null);
          await analyzeImage(pastedFile);
        }
      }
    };
    window.addEventListener("paste", handleGlobalPaste);
    return () => window.removeEventListener("paste", handleGlobalPaste);
  }, []);

  const handleDemoFrameSelect = async (i: number) => {
    analysisController.current?.abort();
    const controller = new AbortController();
    analysisController.current = controller;
    setSelectedFrame(i);
    const frameUrl = `/demo_frames/demo_${i}.jpg`;
    setPreviewUrl(frameUrl);
    setResult(null);
    setGeminiResult(unavailableVision);
    setAnalyzing(true);
    try {
      const response = await fetch(frameUrl, {signal: AbortSignal.any([controller.signal, AbortSignal.timeout(10000)])});
      if (!response.ok) throw new Error('Sample unavailable');
      const blob = await response.blob();
      if (analysisController.current !== controller) return;
      const sampleFile = new File([blob], `demo_${i}.jpg`, {type:'image/jpeg'});
      setFile(sampleFile);
      await analyzeImage(sampleFile);
    } catch {
      if (analysisController.current === controller) {
        setResult(unavailableClassification());
        setAnalyzing(false);
      }
    }
  };

  const handleClearFrame = (e: React.MouseEvent) => {
    e.stopPropagation();
    analysisController.current?.abort();
    analysisController.current = null;
    setAnalyzing(false);
    setFile(null);
    setPreviewUrl(null);
    setSelectedFrame(null);
    setResult(null);
    setGeminiResult(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  return (
    <div className="flex flex-col gap-6 animate-in fade-in duration-500">
      <div className="glass-card p-6 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-heading font-semibold text-foreground mb-1">Experimental Image Classification</h2>
          <p className="text-sm text-muted-foreground">
            Upload an image or select an illustrative sample. Predictions are experimental and are not verified meteorological measurements.
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <span className={`px-2.5 py-1 rounded-xl text-xs font-semibold border ${sourceBadge.badgeClass}`}>
            Experimental image analysis
          </span>
          {selectedCycloneId && (
            <div className="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-300 text-xs shrink-0">
              <Activity className="w-3.5 h-3.5 text-emerald-400" />
              <span suppressHydrationWarning>Target Context: <strong suppressHydrationWarning>{selectedCycloneName || selectedCycloneId}</strong></span>
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        
        {/* Upload/Input Section */}
        <div className="flex flex-col gap-6">
          <input 
            type="file" 
            accept="image/*" 
            className="hidden" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
          />
          <div 
            onClick={() => !analyzing && fileInputRef.current?.click()}
            className={`glass-card p-6 flex-1 min-h-[280px] flex flex-col items-center justify-center border-dashed border-2 transition-all cursor-pointer group relative overflow-hidden ${
              previewUrl ? 'border-primary/50 bg-secondary/20' : 'border-border/60 hover:border-primary/50 bg-secondary/10'
            }`}
          >
            {previewUrl ? (
              <div className="relative w-full h-full flex flex-col items-center justify-center">
                <div className="relative max-h-[220px] w-full flex items-center justify-center rounded-lg overflow-hidden border border-border/80 bg-black/40">
                  <img 
                    src={previewUrl} 
                    alt="Active Frame" 
                    className="max-h-[200px] w-auto object-contain rounded-md transition-transform group-hover:scale-105 duration-300" 
                  />
                  {analyzing && (
                    <div className="absolute inset-0 bg-black/60 backdrop-blur-xs flex flex-col items-center justify-center gap-2 text-primary">
                      <Loader2 className="w-7 h-7 animate-spin text-primary" />
                      <span className="text-xs font-semibold tracking-wide text-white">Running PyTorch Inference...</span>
                      <div className="w-32 h-1 bg-secondary rounded-full overflow-hidden">
                        <div className="w-full h-full bg-primary animate-pulse" />
                      </div>
                    </div>
                  )}
                </div>

                <div className="mt-4 flex items-center justify-between w-full px-2">
                  <span className="text-xs font-medium text-emerald-400 flex items-center gap-1.5">
                    <CheckCircle2 className="w-3.5 h-3.5" />
                    {selectedFrame ? `Sample Frame #${selectedFrame} Loaded` : "Uploaded Frame Active"}
                  </span>
                  <button 
                    onClick={handleClearFrame}
                    className="text-xs text-muted-foreground hover:text-destructive flex items-center gap-1 px-2 py-1 rounded bg-secondary/60 hover:bg-secondary transition-colors"
                  >
                    <X className="w-3 h-3" /> Clear Frame
                  </button>
                </div>
              </div>
            ) : (
               <>
                <div className="w-16 h-16 rounded-full bg-secondary flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <Upload className="w-8 h-8 text-muted-foreground group-hover:text-primary transition-colors" />
                </div>
                <h3 className="text-lg font-medium text-foreground">Drag, Drop, or Paste Image</h3>
                <p className="text-sm text-muted-foreground mt-2 text-center max-w-xs">
                  Supports PNG, JPEG, or Ctrl+V. Max file size: 5MB.
                </p>
                <button className="mt-6 px-6 py-2 rounded-full bg-primary text-primary-foreground text-sm font-medium hover:bg-primary/90 transition-colors shadow-lg shadow-primary/25 pointer-events-none">
                  Browse Files
                </button>
               </>
            )}
          </div>

          <div className="glass-card p-6">
            <h3 className="font-medium text-foreground mb-4 flex items-center gap-2">
              <ImageIcon className="w-5 h-5 text-muted-foreground" />
              Illustrative sample images — acquisition unverified
            </h3>
            <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-hide">
              {[1, 2, 3, 4].map((i) => (
                <button
                  type="button"
                  aria-label={`Select illustrative sample frame ${i}`}
                  aria-pressed={selectedFrame === i}
                  key={i} 
                  onClick={() => handleDemoFrameSelect(i)}
                  className={`min-w-[130px] aspect-square rounded-lg border-2 cursor-pointer transition-all relative overflow-hidden group ${selectedFrame === i ? 'border-primary shadow-lg shadow-primary/30 scale-105 ring-2 ring-primary/40' : 'border-border hover:border-primary/50'}`}
                >
                  <img src={`/demo_frames/demo_${i}.jpg`} alt={`Demo Frame ${i}`} className="absolute inset-0 w-full h-full object-cover group-hover:scale-110 transition-transform duration-300" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />
                  <div className="absolute top-2 right-2 px-1.5 py-0.5 rounded bg-black/60 text-[9px] text-white/90 font-mono border border-white/10">
                    Sample
                  </div>
                  <div className="absolute bottom-2 left-2 text-[11px] font-semibold text-white">Frame #{i}</div>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Results Section */}
        <div className="glass-card p-6 flex flex-col relative overflow-hidden">
          {result && <div className="absolute -top-40 -right-40 w-96 h-96 bg-destructive/10 blur-[100px] rounded-full pointer-events-none" />}
          
          <div className="flex items-center justify-between border-b border-border pb-4 mb-4 flex-wrap gap-2">
            <h3 className="font-heading font-semibold text-lg flex items-center gap-2">
              <Scan className="w-5 h-5 text-primary" />
              Experimental image classification
            </h3>
            <div className="flex items-center gap-2">
              {analyzing ? (
                <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-amber-500/10 text-amber-500 border border-amber-500/20 text-xs font-semibold">
                  <Loader2 className="w-3.5 h-3.5 animate-spin" />
                  Analyzing...
                </span>
              ) : (result || geminiResult) ? (
                <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold bg-emerald-500/10 text-emerald-500 border border-emerald-500/20">
                  <CheckCircle2 className="w-3.5 h-3.5" />
                  {result?.operational_status === 'UNAVAILABLE' ? 'Unavailable' : 'Not scientifically validated'}
                </span>
              ) : (
                <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-secondary text-muted-foreground border border-border text-xs font-semibold">
                  Awaiting Upload
                </span>
              )}
            </div>
          </div>

          {/* Dual AI Engine Badges */}
          <div className="grid grid-cols-2 gap-4 mb-5">
            <div className="p-3.5 rounded-xl bg-secondary/40 border border-border space-y-1">
              <p className="text-[11px] text-muted-foreground font-medium flex items-center justify-between">
                <span>Experimental visual classifier</span>
                <span className="font-mono text-emerald-400 font-bold">{result?.confidence != null ? `${result.confidence}% model score — uncalibrated` : "Unavailable"}</span>
              </p>
              <p className="text-base font-bold text-foreground truncate">
                {result ? result.category : "Awaiting Frame"}
              </p>
              {result && (
                <div className="pt-1 flex items-center gap-1.5 text-[10px] font-mono">
                  {result.is_offline_preset ? (
                    <span className="text-blue-400 font-semibold flex items-center gap-1">
                      Illustrative example — not an inference
                    </span>
                  ) : result.is_trained_weights === true ? (
                    <span className="text-emerald-400 font-semibold flex items-center gap-1">
                      <CheckCircle2 className="w-3 h-3" /> Trained PyTorch Weights
                    </span>
                  ) : (
                    <span className="text-amber-400 font-semibold flex items-center gap-1">
                      Model availability not verified
                    </span>
                  )}
                </div>
              )}
            </div>

            <div className="p-3.5 rounded-xl bg-primary/10 border border-primary/30 space-y-1">
              <p className="text-[11px] text-primary font-medium flex items-center justify-between">
                <span className="flex items-center gap-1"><Sparkles className="w-3 h-3" /> Vision analysis disabled</span>
                {geminiLoading ? (
                  <span className="flex items-center gap-1 font-mono text-[10px] text-primary">
                    <Loader2 className="w-2.5 h-2.5 animate-spin" /> Reasoning...
                  </span>
                ) : (
                  <span className="font-mono text-primary font-bold">Unavailable</span>
                )}
              </p>
              <p className="text-base font-bold text-foreground truncate">
                {geminiLoading ? (
                  <span className="text-xs font-normal text-muted-foreground animate-pulse">Checking availability...</span>
                ) : geminiResult ? (
                  geminiResult.category
                ) : (
                  "Not independently validated"
                )}
              </p>
            </div>
          </div>

          {/* Uncalibrated model warning banner (Fix #6) */}
          {result?.is_uncalibrated_demo && (
            <div className="mb-4 p-3 rounded-xl bg-amber-500/10 border border-amber-500/30 text-amber-300 text-xs flex items-start gap-2.5">
              <ShieldAlert className="w-4 h-4 text-amber-400 shrink-0 mt-0.5" />
              <div>
                <strong className="font-semibold block text-amber-200">Demonstration Mode Notice:</strong>
                <span>{result.warning || "Trained model checkpoint not detected; inference is executing with uncalibrated demonstration initializations."}</span>
              </div>
            </div>
          )}

          {/* Domain Notice (#59) */}
          <div className="mb-4 p-2.5 px-3 rounded-lg bg-blue-500/10 border border-blue-500/20 text-xs text-blue-300 flex items-start gap-2 font-mono">
            <Cpu className="w-4 h-4 text-blue-400 shrink-0 mt-0.5" />
            <div className="text-[11px] leading-relaxed">
              <span className="font-bold text-blue-300 block mb-0.5">Scientific validation required:</span>
              <span>Model scores are not calibrated probabilities or measured wind. Independent imagery, labels and held-out evaluation are required before scientific validation.</span>
            </div>
          </div>

          {/* Grad-CAM & Satellite Image Viewport (Fix #7) */}
          <div className="h-[240px] bg-secondary/30 rounded-xl border border-border relative overflow-hidden flex items-center justify-center group mb-4">
             {previewUrl ? (
                <img src={previewUrl} className="absolute inset-0 w-full h-full object-cover opacity-80" alt="Analyzed" />
             ) : (
                <div className="absolute inset-0 bg-secondary/40 flex items-center justify-center text-muted-foreground text-xs font-mono">
                  Satellite viewport awaiting image input
                </div>
             )}
             
             {result && result.is_cyclone !== false && (
                <>
                 {result.gradcam_data_url ? (
                   <>
                     <div className="absolute top-3 left-3 z-10 bg-black/60 backdrop-blur px-2.5 py-1 rounded-md border border-white/10 text-[11px] text-white/90">
                       Grad-CAM ResNet-50 Heatmap
                     </div>
                     <img 
                       src={result.gradcam_data_url} 
                       alt="Grad-CAM Layer4 Attribution" 
                       className="absolute inset-0 w-full h-full object-cover mix-blend-screen opacity-85 pointer-events-none" 
                     />
                     <div className="absolute bottom-3 right-3 flex items-center gap-2 bg-black/60 backdrop-blur px-2.5 py-1 rounded-md border border-white/10">
                        <span className="text-[10px] text-white/60 uppercase">Low</span>
                        <div className="w-20 h-1.5 rounded-full bg-gradient-to-r from-cyan-500 via-yellow-400 to-red-500" />
                        <span className="text-[10px] text-white/60 uppercase">High</span>
                     </div>
                   </>
                 ) : (
                   <div className="absolute top-3 left-3 z-10 bg-black/70 backdrop-blur px-2.5 py-1 rounded-md border border-white/10 text-[10px] text-amber-300 font-mono">
                     Grad-CAM activation unavailable (Requires live PyTorch ResNet inference)
                   </div>
                 )}
                </>
             )}
          </div>

          {/* Vision analysis disabled Multimodal Diagnostic Breakdown */}
          {geminiResult && (
            <div className="p-4 rounded-xl bg-secondary/30 border border-border space-y-3 mb-4 animate-in fade-in text-xs">
              <h4 className="font-bold text-foreground flex items-center gap-1.5 text-xs">
                <Sparkles className="w-3.5 h-3.5 text-primary" />
                Vision measurements unavailable
              </h4>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5 text-[11px]">
                <div className="p-2 rounded-lg bg-background/60 border border-border/50">
                  <span className="text-muted-foreground block">Eye Structure:</span>
                  <strong className="text-foreground font-medium">{geminiResult.eye_characterization}</strong>
                </div>
                <div className="p-2 rounded-lg bg-background/60 border border-border/50">
                  <span className="text-muted-foreground block">Convective Signature:</span>
                  <strong className="text-foreground font-medium">{geminiResult.convective_signature}</strong>
                </div>
              </div>

              <p className="text-muted-foreground">No calibrated image-derived wind, pressure, Dvorak estimate or operational recommendation is available.</p>
            </div>
          )}

          <div className="flex items-center justify-between gap-3 mt-auto">
             <div className="flex justify-end gap-3 ml-auto">
               <button 
                  disabled={!result || analyzing}
                  onClick={() => {
                    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify({ result, geminiResult }, null, 2));
                    const a = document.createElement('a');
                    a.href = dataStr;
                    a.download = `cyclonet_classification_${Date.now()}.json`;
                    a.click();
                  }}
                  className="disabled:opacity-50 px-4 py-2 rounded-lg border border-border bg-secondary/30 hover:bg-secondary text-xs font-semibold transition-colors cursor-pointer"
               >
                  Export Analysis
               </button>

             </div>
          </div>
        </div>

      </div>
    </div>
  );
}

"use client";
import type { WeatherSystem as ActiveSystem } from "@/types/api";
import { type IngestStatus, type CatalogItem } from "@/types/api";
import React, { useState, useEffect, useRef, useCallback } from "react";
import { AlertCircle, CloudRain, MapPin, Navigation, Wind, ShieldCheck, Play, Activity, RefreshCw, Radio } from "lucide-react";
import dynamic from 'next/dynamic';

import { useActiveCyclone } from "@/hooks/useActiveCyclone";
import { useDataSource } from "@/hooks/useDataSource";
import { useCycloneWebSocket } from "@/hooks/useCycloneWebSocket";
import { useLanguage } from "@/context/LanguageContext";
import { apiFetch, ApiClientError } from "@/lib/api";

const MapComponent = dynamic(() => import('@/components/MapComponent'), { 
  ssr: false,
  loading: () => <div className="w-full h-full bg-zinc-950 flex items-center justify-center text-muted-foreground animate-pulse">Loading Live Map...</div>
});



const getStormDetails = (sys: ActiveSystem | null) => {
  if (!sys) {
    return { 
      basinName: "RSMC New Delhi Jurisdiction", 
      landfall: "Not available",
      landfallLocation: "Awaiting verified source data",
      landfallStatus: "Unknown",
      isCompleted: false,
      surge: "Not available",
      decay: "Not available",
      impactSector: "Nil"
    };
  }

  const isBoB = sys.basin ? sys.basin.toLowerCase().includes("bengal") : (sys.lon > 78);
  const defaultBasin = isBoB ? "West-central & Northwest Bay of Bengal" : "East-central Arabian Sea";

  if (sys.landfall_info) {
    return {
      basinName: sys.basin || defaultBasin,
      landfall: sys.landfall_info.landfall_time_utc || (sys.is_landfall_completed ? "Landfall Completed" : "Coastal Approach"),
      landfallLocation: sys.landfall_info.landfall_location || sys.landfall_info.impact_sector || "Coastal Sector",
      landfallStatus: sys.landfall_info.status || (sys.is_landfall_completed ? "Landfall Completed" : "Active Tracking"),
      isCompleted: !!sys.is_landfall_completed,
      surge: sys.landfall_info.storm_surge_m || "Not available",
      decay: sys.landfall_info.inland_decay || "Inland dissipation",
      impactSector: sys.landfall_info.impact_sector || sys.landfall_info.landfall_location || "Coastal Belt"
    };
  }

  // Check if track_forecast has any point with is_landfall
  const landfallPt = sys.track_forecast?.find((p) => p.is_landfall);
  if (landfallPt) {
    return {
      basinName: sys.basin || defaultBasin,
      landfall: landfallPt.label ? landfallPt.label.split("(")[0].trim() + " UTC" : "Landfall Crossing",
      landfallLocation: landfallPt.label && landfallPt.label.includes("(") ? landfallPt.label.split("(")[1].replace(")", "").trim() : "Coastal Sector",
      landfallStatus: "Landfall Crossing",
      isCompleted: false,
      surge: "Not available",
      decay: "Inland dissipation",
      impactSector: sys.basin || "Coastal Corridor"
    };
  }

  // Check if track_forecast has forecast points
  const forecastPts = sys.track_forecast?.filter((p) => p.is_forecast) || [];
  if (forecastPts.length > 0) {
    const nextFix = forecastPts[0];
    let timing = "+12h Outlook";
    let location = isBoB ? "Approaching East Coast of India" : "Approaching West Coast of India";

    if (nextFix.label) {
      const parts = nextFix.label.split("(");
      const datePart = parts[0].trim();
      if (datePart) timing = `${datePart.split(",")[0]} UTC (+${nextFix.time_offset_hours || 12}h)`;
      if (parts.length > 1) location = parts[1].replace(")", "").trim();
    }

    return {
      basinName: sys.basin || defaultBasin,
      landfall: timing,
      landfallLocation: location,
      landfallStatus: "Approaching Coast",
      isCompleted: false,
      surge: "Not available",
      decay: "Under observation",
      impactSector: location
    };
  }

  // Fallback for systems without active forecast points
  return {
    basinName: sys.basin || defaultBasin,
    landfall: "Not available",
    landfallLocation: sys.basin ? `Archived • ${sys.basin}` : "Regional Ocean Basin",
    landfallStatus: "Unknown",
    isCompleted: false,
    surge: "Not available",
    decay: "Not available",
    impactSector: "Not available"
  };
};

function telemetryMode(system: ActiveSystem | null) {
  if (!system) return "UNAVAILABLE";
  if (system.is_simulation || system.source_type === "DEMO" || system.origin_type === "OPERATIONAL_DRILL") return "SIMULATION";
  if (system.telemetry_type === "HISTORICAL_BEST_TRACK") return "HISTORICAL";
  if (system.is_stale || system.reconciliation_status === "ACTIVE_STALE") return "STALE";
  if (system.reconciliation_status === "ACTIVE_VERIFIED") return "LIVE";
  return "UNVERIFIED";
}

export default function DashboardLiveMonitoringPage() {
  const { selectedCycloneId, selectCyclone, clearSelectedCyclone } = useActiveCyclone();
  const { getConvertedKnots, getConvertedKmh, getConvertedGusts, getConvertedCategory, getSourceBadge } = useDataSource();
  const [activeSystem, setActiveSystem] = useState<ActiveSystem | null>(null);
  const [isSimulation, setIsSimulation] = useState(false);
  const activeRequest = useRef(0);
  const [, setLoading] = useState(true);
  const [ingestStatus, setIngestStatus] = useState<IngestStatus | null>(null);
  const [isSyncingIngest, setIsSyncingIngest] = useState(false);
  const [cyclonesList, setCyclonesList] = useState<CatalogItem[]>([]);

  const { isConnected: isWsConnected, radarAngle } = useCycloneWebSocket();

  const sourceBadge = getSourceBadge();
  const displayKnots = activeSystem ? getConvertedKnots(activeSystem.intensity_knots) : 0;
  const displayKmh = activeSystem ? getConvertedKmh(activeSystem.intensity_knots) : 0;
  const displayGusts = activeSystem ? getConvertedGusts() : null;
  const displayCategory = activeSystem ? getConvertedCategory(activeSystem.intensity_knots) : "Not available";

  useEffect(() => {
    apiFetch<ActiveSystem[]>("/api/cyclones")
      .then(data => {
        if (Array.isArray(data)) setCyclonesList(data);
      })
      .catch(() => {});
  }, []);

  const fetchIngestStatus = () => {
    apiFetch<IngestStatus>("/api/ingest/status")
      .then(data => setIngestStatus(data))
      .catch(() => setIngestStatus(null));
  };

  const [ingestError, setIngestError] = useState<string | null>(null);

  const handleSyncFeeds = async () => {
    setIsSyncingIngest(true);
    setIngestError(null);
    try {
      const data = await apiFetch<IngestStatus>("/api/ingest/status");
      setIngestStatus(data);
      clearSelectedCyclone();
      await fetchActiveSystems(false);
    } catch (err: unknown) {
      if (err instanceof ApiClientError && err.status === 429) {
        setIngestError("Too many refreshes. Please wait a moment and try again.");
      } else {
        setIngestError("Live data could not be refreshed. The feed may be unavailable; try again shortly.");
      }
    } finally {
      setIsSyncingIngest(false);
    }
  };

  const fetchActiveSystems = useCallback(async (simulate: boolean = false, cycloneId?: string | null) => {
    const requestId = ++activeRequest.current;
    setLoading(true);
    let path = "/api/active-systems";
    const targetId = cycloneId || (simulate ? selectedCycloneId : null);
    if (simulate || targetId) {
      path += `?simulate=true${targetId ? `&cyclone_id=${encodeURIComponent(targetId)}` : ""}`;
    }
    try {
      const data = await apiFetch<ActiveSystem[]>(path);
      if (requestId !== activeRequest.current) return;
      if (data && data.length > 0) {
        setActiveSystem(data[0]);
        setIsSimulation(telemetryMode(data[0]) === "SIMULATION");
      } else {
        setActiveSystem(null);
        setIsSimulation(false);
      }
    } catch (err) {
      if (requestId !== activeRequest.current) return;
      setActiveSystem(null);
      setIsSimulation(false);
      console.warn("Notice: Active systems feed temporarily unavailable or initializing:", err);
    } finally {
      if (requestId === activeRequest.current) setLoading(false);
    }
  }, [selectedCycloneId]);

  const invalidateActiveRequest = useCallback(() => { activeRequest.current++; }, []);
  useEffect(() => {
    fetchIngestStatus();
    const interval = setInterval(() => {
      fetchIngestStatus();
      fetchActiveSystems(Boolean(selectedCycloneId), selectedCycloneId);
    }, 30000);
    return () => { clearInterval(interval); invalidateActiveRequest(); };
  }, [selectedCycloneId, fetchActiveSystems, invalidateActiveRequest]);

  useEffect(() => {
    let targetId = selectedCycloneId;
    if (typeof window !== "undefined") {
      const params = new URLSearchParams(window.location.search);
      const simParam = params.get("simulate");
      if (simParam && simParam !== "true") {
        targetId = simParam;
        selectCyclone(simParam);
      }
    }
    if (targetId) {
      fetchActiveSystems(true, targetId);
    } else {
      fetchActiveSystems(false);
    }
  }, [selectedCycloneId, fetchActiveSystems, selectCyclone]);

  const stormMeta = getStormDetails(activeSystem);
  const mode = telemetryMode(activeSystem);
  const modeLabel = {UNAVAILABLE: "BASIN STATUS UNCERTAIN", SIMULATION: "SYNTHETIC EXERCISE DRILL",
    HISTORICAL: "HISTORICAL ARCHIVE REPLAY", STALE: "STALE SOURCE OBSERVATION",
    LIVE: "CURRENT SOURCE OBSERVATION", UNVERIFIED: "SOURCE STATUS UNVERIFIED"}[mode];
  const modeDescription = {UNAVAILABLE: "No current source observations are available.",
    SIMULATION: "Synthetic scenario for demonstration; not a measured storm.",
    HISTORICAL: "Historical best-track replay. Not a current storm.",
    STALE: "Retained source observation; current conditions are unverified.",
    LIVE: "Current source observation for experimental decision support.",
    UNVERIFIED: "Source provenance or freshness could not be verified."}[mode];
  const modeClass = mode === "SIMULATION" ? "bg-purple-500/15 text-purple-400 border-purple-500/30"
    : mode === "LIVE" ? "bg-rose-500/15 text-rose-400 border-rose-500/30"
    : mode === "HISTORICAL" ? "bg-blue-500/15 text-blue-400 border-blue-500/30"
    : "bg-amber-500/15 text-amber-500 border-amber-500/30";

  // Expose live UI screen telemetry to window context for CycloNet AI assistant
  useEffect(() => {
    if (typeof window !== "undefined") {
      const meta = getStormDetails(activeSystem);
      window.__cyclonet_current_context = {
        page: "Live Monitoring",
        isSimulation,
        activeSystem: activeSystem ? {
          id: activeSystem.id,
          name: activeSystem.name,
          category: activeSystem.category,
          basin: meta.basinName,
          lat: activeSystem.lat,
          lon: activeSystem.lon,
          coordinates: `${activeSystem.lat.toFixed(1)}°N, ${activeSystem.lon.toFixed(1)}°E`,
          intensity_knots: activeSystem.intensity_knots,
          wind_kmh: (activeSystem.intensity_knots == null ? null : Math.round(activeSystem.intensity_knots * 1.852)),
          gusting_kmh: (activeSystem.intensity_knots == null ? null : Math.round(activeSystem.intensity_knots * 1.852 * 1.05)),
          track_points_count: activeSystem.track_forecast?.length || 0,
          current_position_label: `${activeSystem.lat.toFixed(1)}°N, ${activeSystem.lon.toFixed(1)}°E`,
          landfall: meta.landfall,
          landfallLocation: meta.landfallLocation,
          simulation_active: isSimulation,
        } : null,
        basin_status: ingestStatus?.basin_status ?? "STATUS_UNCERTAIN",
        observation_status: mode
      };
    }
  }, [activeSystem, isSimulation, ingestStatus, mode]);

  return (
    <div className="flex flex-col gap-6 animate-in fade-in duration-500">
      
      {ingestError && (
        <div className="p-3 px-4 rounded-xl bg-rose-500/15 border border-rose-500/30 text-rose-600 dark:text-rose-400 text-xs flex items-center justify-between shadow-xs">
          <span className="font-medium">⚠️ {ingestError}</span>
          <button onClick={() => setIngestError(null)} className="text-xs font-semibold hover:underline cursor-pointer ml-4">Dismiss</button>
        </div>
      )}

      {/* Live Ingestion Feed Bar */}
      <div className="p-3 px-4 rounded-xl bg-surface-glass border border-border backdrop-blur-md flex flex-wrap items-center justify-between gap-3 text-xs shadow-xs">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2">
            <Radio className="w-4 h-4 text-emerald-500 dark:text-emerald-400 animate-pulse" />
            <span className="font-semibold text-foreground">Live Ingestion:</span>
          </div>
          <div className="flex items-center gap-2 text-muted-foreground">
            {isWsConnected ? (
              <span className="flex items-center gap-1.5 px-2 py-0.5 rounded-md bg-emerald-500/15 border border-emerald-500/30 font-mono text-[11px] text-emerald-400 font-bold">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
                WS Live ({Math.round(radarAngle)}° Sweep Sim)
              </span>
            ) : (
              <span className="flex items-center gap-1.5 px-2 py-0.5 rounded-md bg-zinc-800/80 border border-zinc-700 font-mono text-[11px] text-zinc-400">
                <span className="w-1.5 h-1.5 rounded-full bg-amber-400" />
                HTTP Polling
              </span>
            )}
            <span className="px-2 py-0.5 rounded-md bg-secondary border border-border font-mono text-[11px] text-muted-foreground font-medium">
              IMD RSMC: {ingestStatus?.sources_status?.IMD_RSMC ?? "UNAVAILABLE"}
            </span>
            <span className="px-2 py-0.5 rounded-md bg-secondary border border-border font-mono text-[11px] text-muted-foreground font-medium">
              JTWC/NOAA: {ingestStatus?.sources_status?.JTWC_NOAA ?? "UNAVAILABLE"}
            </span>
            <span className="px-2 py-0.5 rounded-md bg-blue-500/10 border border-blue-500/20 font-mono text-[11px] text-blue-600 dark:text-blue-400 font-medium">
              Satellite observations unavailable
            </span>
          </div>
          {ingestStatus?.last_sync && (
            <span className="hidden sm:inline text-muted-foreground text-[11px]">
              • Last Sync: {new Date(ingestStatus.last_sync).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
            </span>
          )}
        </div>

        <div className="flex items-center gap-2">
          <select
            aria-label="Storm or live source selection"
            value={
              !activeSystem
                ? "LIVE_SCAN"
                : (selectedCycloneId || activeSystem.id)
            }
            onChange={(e) => {
              const val = e.target.value;
              if (val === "LIVE_SCAN") {
                clearSelectedCyclone();
                fetchActiveSystems(false);
              } else {
                selectCyclone(val);
                fetchActiveSystems(true, val);
              }
            }}
            className="px-3 py-1.5 rounded-lg bg-secondary border border-border text-foreground text-xs font-semibold focus:outline-none focus:ring-1 focus:ring-primary cursor-pointer shadow-xs"
          >
            <option value="LIVE_SCAN">
              {mode === "LIVE" ? `Current source: ${activeSystem?.name}` : "Live ingestion: check source status"}
            </option>
            {cyclonesList.map((c) => {
              const displayName = c.name.startsWith("Cyclone") || c.name.startsWith("Deep") || c.name.startsWith("Super") 
                ? c.name 
                : `Cyclone ${c.name}`;
              const isDrill = c.is_simulation;
              return (
                <option key={c.id} value={c.id}>
                  {isDrill ? "🧪 Drill: " : "🏛️ Historical: "}{displayName} ({c.year})
                </option>
              );
            })}
          </select>

          <span className={`px-2.5 py-1 rounded-full text-xs font-bold border flex items-center gap-1.5 ${modeClass}`} title={modeDescription}>
            <span className="w-1.5 h-1.5 rounded-full bg-current animate-pulse" />
            {modeLabel}
          </span>

          <button
            onClick={handleSyncFeeds}
            disabled={isSyncingIngest}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-blue-500/10 hover:bg-blue-500/20 border border-blue-500/30 text-blue-600 dark:text-blue-400 text-xs font-semibold transition-all disabled:opacity-50 cursor-pointer hover:scale-105 active:scale-95 shadow-xs"
            title="Reload the latest backend observations. Starting a new ingestion job requires administrator access."
          >
            <RefreshCw className={`w-3.5 h-3.5 ${isSyncingIngest ? "animate-spin" : ""}`} />
            <span>{isSyncingIngest ? "Refreshing..." : "Refresh live data"}</span>
          </button>
        </div>
      </div>

      {/* Explicit Mode & Civil Defense Advisory Banner (#34 & #36) */}
      <div className="p-3 px-4 rounded-xl border flex flex-col md:flex-row md:items-center justify-between gap-3 text-xs bg-secondary/30 border-border">
        <div className="flex items-center gap-2.5 flex-wrap">
          <span className={`px-2 py-0.5 rounded font-mono font-bold text-[11px] uppercase tracking-wider border ${modeClass}`}>
            {modeLabel}
          </span>
          <span className="text-muted-foreground">{modeDescription}</span>
        </div>
        <div className="text-[10.5px] text-muted-foreground md:text-right shrink-0">
          <span className="font-semibold text-foreground/80">Civil Defense Advisory:</span> Statutory evacuation directives follow IMD (RSMC New Delhi) and NDMA orders.
        </div>
      </div>

      {/* Unavailable source status with explicit historical replay selection */}
      {!activeSystem && (
        <div className="glass-card p-4 sm:p-5 border-emerald-500/30 bg-emerald-950/10 backdrop-blur-md flex flex-col lg:flex-row lg:items-center justify-between gap-4 shadow-sm animate-in fade-in duration-300">
          <div className="flex items-start sm:items-center gap-3.5">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/15 text-emerald-400 flex items-center justify-center shrink-0 border border-emerald-500/30">
              <ShieldCheck className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2 flex-wrap">
                <span className="px-2 py-0.5 rounded text-[11px] font-mono font-bold bg-emerald-500/20 text-emerald-400 border border-emerald-500/30">
                  NO VERIFIED CURRENT OBSERVATIONS
                </span>
                <span className="text-xs text-muted-foreground font-mono">
                  Source coverage or freshness unverified
                </span>
              </div>
              <p className="text-xs text-muted-foreground mt-1">
                Current basin conditions could not be verified. Retry live sources or explicitly choose a historical simulation.
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2 flex-wrap shrink-0">
            <button
              onClick={() => {
                selectCyclone("BOB03-2020");
                fetchActiveSystems(true, "BOB03-2020");
              }}
              className="px-3.5 py-1.5 rounded-lg bg-primary hover:bg-primary/90 text-primary-foreground text-xs font-bold transition-all cursor-pointer flex items-center gap-1.5 shadow-xs"
            >
              <Play className="w-3 h-3 fill-current" />
              Load Super Cyclone Amphan
            </button>
            <button
              onClick={() => {
                selectCyclone("ARB01-2023");
                fetchActiveSystems(true, "ARB01-2023");
              }}
              className="px-3 py-1.5 rounded-lg bg-secondary hover:bg-secondary/80 text-foreground text-xs font-semibold border border-border transition-all cursor-pointer"
            >
              Cyclone Biparjoy
            </button>
          </div>
        </div>
      )}

      {/* Top Stats Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        
        {/* Stat Card 1: System Status */}
        <div className="glass-card p-5 flex flex-col gap-4">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm text-muted-foreground font-medium">
                {activeSystem ? "Active System" : "Basin Status"}
              </p>
              <h3 className="text-2xl font-heading font-bold text-foreground mt-1">
                {activeSystem ? activeSystem.name : "Current status unavailable"}
              </h3>
            </div>
            <div className={`p-2 rounded-lg ${activeSystem ? "bg-destructive/10 text-destructive" : "bg-emerald-500/10 text-emerald-500 dark:text-emerald-400"}`}>
              {activeSystem ? <AlertCircle className="w-5 h-5" /> : <ShieldCheck className="w-5 h-5" />}
            </div>
          </div>
          <div className="mt-2 text-sm">
            {activeSystem ? (
              <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-destructive/20 text-destructive border border-destructive/20 font-semibold text-xs">
                <span className="w-1.5 h-1.5 rounded-full bg-destructive animate-pulse" />
                {displayCategory}
              </span>
            ) : (
              <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 font-semibold text-xs">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                Basin conditions uncertain
              </span>
            )}
          </div>
        </div>

        {/* Stat Card 2: Surface / Sustained Winds */}
        <div className="glass-card p-5 flex flex-col gap-4">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm text-muted-foreground font-medium">
                {activeSystem ? `Max Sustained Wind (${sourceBadge.shortLabel})` : "Prevailing Basin Winds"}
              </p>
              <h3 className="text-2xl font-heading font-bold text-foreground mt-1">
                {activeSystem
                  ? `${displayKmh ?? "Not available"} km/h (${displayKnots ?? "Not available"} kts)`
                  : "Not available"}
              </h3>
            </div>
            <div className="p-2 bg-secondary rounded-lg border border-border">
              <Wind className="w-5 h-5 text-foreground" />
            </div>
          </div>
          <div className="mt-2 flex items-center gap-2 text-sm text-muted-foreground">
            {activeSystem ? (
              <span className="text-emerald-600 dark:text-emerald-400 font-medium">
                Gusting to {displayGusts ?? "Not available"} km/h
              </span>
            ) : (
              <span className="text-emerald-600 dark:text-emerald-400 font-medium">No measured wind available</span>
            )}
            <span>• {sourceBadge.avgWindow}</span>
          </div>
        </div>

        {/* Stat Card 3: Location / Basins */}
        <div className="glass-card p-5 flex flex-col gap-4">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm text-muted-foreground font-medium">
                {activeSystem ? "Current Center Fix" : "Monitored Basins"}
              </p>
              <h3 className="text-2xl font-heading font-bold text-foreground mt-1">
                {activeSystem
                  ? `${activeSystem.lat.toFixed(1)}°N, ${activeSystem.lon.toFixed(1)}°E`
                  : "Arabian Sea & BoB"}
              </h3>
            </div>
            <div className="p-2 bg-secondary rounded-lg border border-border">
              <MapPin className="w-5 h-5 text-foreground" />
            </div>
          </div>
          <div className="mt-2 flex items-center gap-2 text-sm text-muted-foreground">
            <span>{stormMeta.basinName}</span>
          </div>
        </div>

        {/* Stat Card 4: Outlook */}
        <div className="glass-card p-5 flex flex-col gap-4">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm text-muted-foreground font-medium">
                {activeSystem ? "Est. Landfall" : "5-Day Cyclogenesis"}
              </p>
              <h3 className="text-2xl font-heading font-bold text-foreground mt-1">
                {stormMeta.landfall}
              </h3>
            </div>
            <div className="p-2 bg-secondary rounded-lg border border-border">
              <Navigation className="w-5 h-5 text-foreground" />
            </div>
          </div>
          <div className="mt-2 flex items-center gap-2 text-sm text-muted-foreground">
            <span>{stormMeta.landfallLocation}</span>
          </div>
        </div>
      </div>

      {/* Main Map & Sidebar Split */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        
        {/* Map Container */}
        <div className="glass-card lg:col-span-2 min-h-[520px] flex flex-col p-1 relative overflow-hidden">
          {/* Interactive Leaflet Map */}
          <div className="w-full h-full rounded-xl relative overflow-hidden border border-border/50 z-0">
            <MapComponent activeSystem={activeSystem} />
          </div>

          {/* Bottom Simulation Prompt when no storm is active */}
          {!activeSystem && (
            <div className="absolute bottom-4 left-4 right-4 z-10 p-3 px-4 rounded-xl bg-card/95 backdrop-blur-md border border-border flex flex-col sm:flex-row items-center justify-between gap-3 shadow-xl">
              <div className="flex items-center gap-2.5 text-xs text-muted-foreground">
                <Activity className="w-4 h-4 text-emerald-500 dark:text-emerald-400 shrink-0" />
                <span>Current storm status is unavailable. Historical visualization remains available.</span>
              </div>
              <button
                onClick={() => fetchActiveSystems(true)}
                className="px-3.5 py-1.5 rounded-lg bg-secondary hover:bg-secondary/80 border border-border text-foreground text-xs font-semibold flex items-center gap-2 transition-all cursor-pointer whitespace-nowrap shadow-xs hover:scale-[1.02]"
              >
                <Play className="w-3.5 h-3.5 fill-current text-amber-500 dark:text-amber-400" />
                Load Biparjoy (2023) Simulation
              </button>
            </div>
          )}
        </div>

        {/* Right Sidebar Details */}
        <div className="flex flex-col gap-6">
          <div className="glass-card p-5">
            <h3 className="font-heading font-semibold text-lg border-b border-border pb-3 mb-4">
              {activeSystem ? "Latest Storm Bulletins" : "Source Availability"}
            </h3>
            <div className="space-y-4">
              {activeSystem ? (
                (() => {
                  const basinName = activeSystem.basin || "North Indian Ocean";

                  const dynamicBulletins = [
                    { time: activeSystem.observation_time_utc ?? "Issue time not available",
                      text: `${activeSystem.name}: ${activeSystem.intensity_knots ?? "Not available"} kt. Source: ${activeSystem.source ?? "Not available"}.`, type: "info" },
                    { time: "Experimental analysis", text: "Landfall, rainfall, surge and protective actions require current official advisories.", type: "info" },
                  ];

                  return dynamicBulletins.map((bulletin, i) => (
                    <div key={i} className="flex gap-3 relative">
                      <div className="mt-1">
                        {bulletin.type === 'alert' ? 
                          <AlertCircle className="w-4 h-4 text-destructive" /> : 
                          <CloudRain className="w-4 h-4 text-blue-500" />
                        }
                      </div>
                      <div>
                        <span className="text-xs text-muted-foreground font-medium">{bulletin.time}</span>
                        <p className="text-sm text-foreground/90 mt-0.5">{bulletin.text}</p>
                      </div>
                    </div>
                  ));
                })()
              ) : (
                [
                  { time: "Source unavailable", text: "No verified current observations are available. Basin conditions are uncertain; consult official agencies.", type: "info" },
                ].map((bulletin, i) => (
                  <div key={i} className="flex gap-3 relative">
                    <div className="mt-1">
                      <div className="w-2 h-2 rounded-full bg-emerald-500 mt-1" />
                    </div>
                    <div>
                      <span className="text-xs text-muted-foreground font-medium">{bulletin.time}</span>
                      <p className="text-sm text-foreground/90 mt-0.5">{bulletin.text}</p>
                    </div>
                  </div>
                ))
              )}
            </div>
            <a 
              href={activeSystem ? `/forecast?cyclone_id=${encodeURIComponent(activeSystem.id)}` : "/forecast"} 
              className="w-full mt-6 py-2.5 rounded-lg bg-secondary hover:bg-secondary/80 border border-border text-sm font-semibold transition-all text-foreground flex items-center justify-center gap-2 text-center cursor-pointer shadow-xs hover:scale-[1.005]"
            >
              <span>View complete analytics & forecast</span>
            </a>
          </div>

          <div className="glass-card p-5 flex-1">
             <div className="flex items-center justify-between border-b border-border pb-3 mb-4">
               <h3 className="font-heading font-semibold text-lg">
                {activeSystem ? "Telemetry & Model Attribution" : "System Diagnostics"}
               </h3>
               {activeSystem && (
                 <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-blue-500/10 text-blue-500 border border-blue-500/20 font-mono">
                   {activeSystem.telemetry_type || modeLabel}
                 </span>
               )}
             </div>

             {activeSystem ? (
               <div className="space-y-4">
                 <div className="bg-secondary/30 p-3 rounded-xl border border-border/60 text-xs space-y-2">
                   <div className="flex justify-between items-center text-[11px]">
                     <span className="text-muted-foreground">0h Center Eye Fix:</span>
                     <span className="font-semibold text-foreground flex items-center gap-1">
                       <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                       {mode === "SIMULATION" ? "Simulated" : "Source fix"} ({activeSystem.lat.toFixed(1)}°N, {activeSystem.lon.toFixed(1)}°E)
                     </span>
                   </div>
                   <div className="flex justify-between items-center text-[11px]">
                     <span className="text-muted-foreground">Sustained Core Wind:</span>
                     <span className="font-semibold text-foreground">
                       {mode === "SIMULATION" ? "Simulated" : "Source value"} ({activeSystem.intensity_knots ?? "Not available"} KT)
                     </span>
                   </div>
                   <div className="flex justify-between items-center text-[11px]">
                     <span className="text-muted-foreground">Dvorak Intensity:</span>
                     <span className="font-mono font-bold text-primary">
                       {activeSystem.dvorak_t || "Not available"} <span className="font-normal text-[10px] text-muted-foreground">(Parametric Wind Scale)</span>
                     </span>
                   </div>
                   <div className="flex justify-between items-center text-[11px]">
                     <span className="text-muted-foreground">Forward Trajectory:</span>
                     <span className="font-semibold text-foreground text-[10.5px]">
                       {activeSystem.track_generation_method ?? "Forecast unavailable"}
                     </span>
                   </div>
                 </div>

                 <p className="text-[11px] text-muted-foreground leading-relaxed">
                   ℹ️ <strong className="text-foreground">Transparency Note:</strong> Live center fixes and core wind speeds are ingested from external feeds. Forward tracks and the Dvorak T-number are CycloNet-derived parametric estimates. Experimental image classification is available in the <a href="/classification" className="text-primary underline font-medium">Classification</a> tab.
                 </p>

                 <div className="space-y-3 pt-2 border-t border-border/50">
                   <div>
                     <div className="flex justify-between text-xs mb-1.5">
                       <span className="text-muted-foreground">Telemetry Provenance</span>
                       <span className="font-semibold text-emerald-600 dark:text-emerald-400">Accuracy not independently verified</span>
                     </div>
                     <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
                       <div className="h-full bg-emerald-500 w-0 rounded-full" />
                     </div>
                   </div>
                   <div>
                     <div className="flex justify-between text-xs mb-1.5">
                       <span className="text-muted-foreground">Trajectory Kinematic Fit</span>
                       <span className="font-semibold text-foreground">Not independently validated</span>
                     </div>
                     <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
                       <div className="h-full bg-primary/70 w-0 rounded-full" />
                     </div>
                   </div>
                 </div>
               </div>
             ) : (
               <div className="space-y-6">
                  <div>
                    <div className="flex justify-between text-sm mb-2">
                      <span className="text-muted-foreground">Satellite Ingestion Status</span>
                      <span className="font-semibold text-emerald-600 dark:text-emerald-400">Unavailable</span>
                    </div>
                    <div className="h-2 rounded-full bg-secondary overflow-hidden">
                      <div className="h-full bg-emerald-500 w-0 rounded-full" />
                    </div>
                  </div>
                  <div>
                    <div className="flex justify-between text-sm mb-2">
                      <span className="text-muted-foreground">Organized Vortex Anomaly</span>
                      <span className="font-semibold text-foreground">Not available</span>
                    </div>
                    <div className="h-2 rounded-full bg-secondary overflow-hidden">
                      <div className="h-full bg-primary/40 w-[0%] rounded-full" />
                    </div>
                  </div>
                  <div>
                    <div className="flex justify-between text-sm mb-1">
                      <span className="text-muted-foreground">5-Day Cyclogenesis Risk (IMD TWO)</span>
                      <span className="font-semibold text-emerald-600 dark:text-emerald-400">Not available</span>
                    </div>
                    <p className="text-[10px] text-muted-foreground mb-2">
                      No current agency-issued outlook was retrieved. Missing data does not establish calm.
                    </p>
                    <div className="h-2 rounded-full bg-secondary overflow-hidden">
                      <div className="h-full bg-emerald-500 w-[0%] rounded-full" />
                    </div>
                  </div>
               </div>
             )}
          </div>
        </div>

      </div>
    </div>
  );
}

"use client";
import type { WeatherSystem as ActiveSystem } from "@/types/api";
import { type SurgeCalculation, type SurgeSector, type RainfallPathway, type Briefing, type DispatchResult, type CatalogItem } from "@/types/api";
import { ObservationValue } from "@/components/ObservationValue";
import React, { useState, useEffect, useSyncExternalStore } from "react";
import { Building2, Zap, Navigation, Coins, Waves, RefreshCw, CheckCircle2, Radio, Siren, Search, ShieldAlert, Sparkles, CloudRain, Layers, Cpu, CheckCircle, X, Send, Copy, ArrowRight, Check, AlertOctagon, Terminal } from "lucide-react";
import { useActiveCyclone } from "@/hooks/useActiveCyclone";
import { useDataSource } from "@/hooks/useDataSource";
import { getApiBaseUrl, apiFetch } from "@/lib/api";
import { POWER_SUBSTATIONS as SCENARIO_POWER_SUBSTATIONS, EVACUATION_ROUTES as SCENARIO_EVACUATION_ROUTES, MEDICAL_SHELTERS as SCENARIO_MEDICAL_SHELTERS, PARAMETRIC_INSURANCE_TRIGGERS as SCENARIO_PARAMETRIC_INSURANCE_TRIGGERS, COASTAL_INUNDATION_ZONES as SCENARIO_COASTAL_INUNDATION_ZONES, calculateSubstationVulnerability, calculateRouteVulnerability, calculateShelterSuitability } from "@/lib/infrastructureData";



import { catalogObservation } from '@/lib/catalogObservation';
const PRESET_STORMS: {id:string;name:string;basin:string;category:string;knots:number|null}[] = [];

function subscribeLocation(notify: () => void) { window.addEventListener("popstate", notify); return () => window.removeEventListener("popstate", notify); }
function readTab() { const tab = new URLSearchParams(window.location.search).get("tab"); return tab === "surge" ? "surge_rain" : tab ?? "grid"; }
export default function InfrastructurePage() {
  const [scenarioMode, setScenarioMode] = useState(false);
  const PARAMETRIC_INSURANCE_TRIGGERS = scenarioMode ? SCENARIO_PARAMETRIC_INSURANCE_TRIGGERS : [];
  const POWER_SUBSTATIONS = scenarioMode ? SCENARIO_POWER_SUBSTATIONS : [];
  const MEDICAL_SHELTERS = scenarioMode ? SCENARIO_MEDICAL_SHELTERS : [];
  const EVACUATION_ROUTES = scenarioMode ? SCENARIO_EVACUATION_ROUTES : [];
  const { selectedCycloneId, selectCyclone } = useActiveCyclone();
  const { getConvertedKnots, getConvertedKmh, getConvertedGusts, getConvertedCategory, getSourceBadge } = useDataSource();

  const sourceBadge = getSourceBadge();
  const [system, setSystem] = useState<ActiveSystem | null>(null);
  const [loading, setLoading] = useState(true);
  const [cyclonesList, setCyclonesList] = useState(PRESET_STORMS);
  const queryTab = useSyncExternalStore(subscribeLocation, readTab, () => "grid");
  const [tabOverride, setActiveTab] = useState<string | null>(null);
  const activeTab = tabOverride ?? queryTab;
  const [infraFilter, setInfraFilter] = useState<"all" | "critical" | "high">("all");
  const [searchFilter, setSearchFilter] = useState<string>("" );
  const [regionFilter, setRegionFilter] = useState<string>("ALL");
  const [toast, setToast] = useState<string | null>(null);

  // Hydrodynamic Surge & GEE Simulator State
  const [simPressureHpa, setSimPressureHpa] = useState<number>(945);
  const [simWindKts, setSimWindKts] = useState<number>(115);
  const [simTideM, setSimTideM] = useState<number>(1.8);
  const simForwardSpeed = 18;
  const [simAngleDeg, setSimAngleDeg] = useState<number>(75);
  const simRainMm = 240;
  const [surgeCalcData, setSurgeCalcData] = useState<SurgeCalculation | null>(null);
  const [surgeSectors, setSurgeSectors] = useState<SurgeSector[]>([]);
  const [rainfallPathways, setRainfallPathways] = useState<RainfallPathway[]>([]);
  const [, setGeeLayers] = useState<Record<string, unknown>[]>([]);

  // Deterministic source and scenario briefing state
  const [briefingModalOpen, setBriefingModalOpen] = useState(false);
  const [briefingLoading, setBriefingLoading] = useState(false);
  const [briefingData, setBriefingData] = useState<Briefing | null>(null);
  const briefingLanguage = "en";

  // Automated Multi-Channel Warning Dispatcher State
  const [dispatchRegion, setDispatchRegion] = useState<string>("Sundarbans & Odisha Coastal Corridor");
  const [dispatchRiskLevel, setDispatchRiskLevel] = useState<string>("CRITICAL");
  const [dispatchChannels, setDispatchChannels] = useState<string[]>(["CAP", "SMS", "SACHET", "SIREN", "VHF"]);
  const [dispatchLoading, setDispatchLoading] = useState<boolean>(false);
  const [, setDispatchStep] = useState<number>(0);
  const [dispatchResult, setDispatchResult] = useState<DispatchResult | null>(null);
  const [dispatchViewerTab, setDispatchViewerTab] = useState<"cap" | "sms" | "sachet" | "siren" | "vhf" | "directives">("cap");

  // Parametric insurance simulation state
  const [insuranceSimulationTier, setInsuranceSimulationTier] = useState<number>(0);
  const [isSimulatingPayout, setIsSimulatingPayout] = useState(false);
  const [, setPayoutSuccess] = useState(false);

  const showToast = (msg: string) => {
    setToast(msg);
    setTimeout(() => setToast(null), 3000);
  };

  useEffect(() => {
    async function fetchAllCyclones() {
      try {
        const res = await fetch(`${getApiBaseUrl()}/api/history/search`);
        if (res.ok) {
          const data = await res.json();
          if (Array.isArray(data) && data.length > 0) {
            setCyclonesList(data.map((c: CatalogItem) => ({
              ...catalogObservation(c),
              name: c.name.startsWith("Cyclone ") || c.name.startsWith("Deep Depression") || c.name.startsWith("Depression") || c.name.startsWith("Super Cyclone") || c.name.includes("Cyclone") ? c.name : `Cyclone ${c.name}`,
            })));
          }
        }
      } catch (err) {
        console.error("Failed to load full cyclone list", err);
      }
    }
    fetchAllCyclones();
  }, []);

  useEffect(() => {
    const controller = new AbortController();
    const fetchSystem = async () => {
      setLoading(true);
      setSystem(null);
      try {
        const query = selectedCycloneId ? `?cyclone_id=${encodeURIComponent(selectedCycloneId)}` : "";
        const res = await fetch(`${getApiBaseUrl()}/api/active-systems${query}`, {signal:controller.signal});
        if (!res.ok) throw new Error("Source unavailable");
        const data = await res.json();
        if (!controller.signal.aborted) setSystem(data?.[0] ?? null);
      } catch {
        if (!controller.signal.aborted) setToast("Source unavailable. Operational conditions are not verified.");
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    };
    void fetchSystem();
    return () => controller.abort();
  }, [selectedCycloneId]);

  const rawKnots = scenarioMode ? simWindKts : system?.intensity_knots ?? null;
  const knots = getConvertedKnots(rawKnots);
  const kmh = getConvertedKmh(rawKnots);
  const displayCategory = getConvertedCategory(rawKnots);
  const surgeM = scenarioMode ? surgeCalcData?.peak_surge_height_m ?? null : null;

  // Explicit scenario calculations; changes cancel and clear older results.
  useEffect(() => {
    const controller = new AbortController();
    async function fetchSurgeAndGee() {
      setSurgeCalcData(null); setSurgeSectors([]); setRainfallPathways([]); setGeeLayers([]);
      if (!scenarioMode) return;
      try {
        const lat = system?.lat || 18.2;
        const lon = system?.lon || 84.8;
        const basin = system?.basin || "Bay of Bengal";

        const [surgeRes, secRes, pathRes, layerRes] = await Promise.all([
          fetch(`${getApiBaseUrl()}/api/surge/calculate?knots=${simWindKts}&pressure_hpa=${simPressureHpa}&forward_speed=${simForwardSpeed}&angle_deg=${simAngleDeg}&tide_m=${simTideM}&basin=${encodeURIComponent(basin)}`, {signal:controller.signal}),
          fetch(`${getApiBaseUrl()}/api/surge/profile?name=${encodeURIComponent(system?.name || "Cyclone")}&lat=${lat}&lon=${lon}&knots=${simWindKts}`, {signal:controller.signal}),
          fetch(`${getApiBaseUrl()}/api/gee/rainfall-pathways?lat=${lat}&lon=${lon}&rain_mm=${simRainMm}`, {signal:controller.signal}),
          fetch(`${getApiBaseUrl()}/api/gee/layers`, {signal:controller.signal})
        ]);

        if (controller.signal.aborted) return;
        if (![surgeRes,secRes,pathRes,layerRes].every(res => res.ok)) throw new Error("Scenario unavailable");
        if (surgeRes.ok) setSurgeCalcData(await surgeRes.json());
        if (secRes.ok) {
          const d = await secRes.json();
          setSurgeSectors(d.sectors || []);
        }
        if (pathRes.ok) {
          const d = await pathRes.json();
          setRainfallPathways(d.pathways || []);
        }
        if (layerRes.ok) {
          const d = await layerRes.json();
          setGeeLayers(d.layers || []);
        }
      } catch (err) {
        console.error("Error fetching surge & GEE telemetry", err);
      }
    }
    const debounce = window.setTimeout(() => void fetchSurgeAndGee(), 350);
    return () => { controller.abort(); window.clearTimeout(debounce); };
  }, [scenarioMode, system, simWindKts, simPressureHpa, simTideM, simForwardSpeed, simAngleDeg, simRainMm]);

  // Handle Multi-Channel Early Warning Dispatch
  const handleExecuteDispatch = async () => {
    if (dispatchLoading || !scenarioMode) return;
    if (!surgeCalcData) { showToast("Scenario calculation unavailable. Retry before generating a draft."); return; }
    setDispatchLoading(true);
    setDispatchStep(1);



    try {
      const payload = {
        region: dispatchRegion,
        risk_level: dispatchRiskLevel,
        surge: surgeCalcData?.peak_surge_height_m || surgeM,
        wind: simWindKts,
        channels: dispatchChannels,
        cyclone_name: system?.name || "Exercise cyclone"
      };
      const data = await apiFetch<DispatchResult>("/api/alerts/dispatch", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      {
        setTimeout(() => {
          setDispatchResult(data);
          setDispatchLoading(false);
          setDispatchStep(5);
          showToast(`Exercise generated. No real broadcast was sent.`);
        }, 2600);
      }
    } catch {
      setDispatchResult(null);
      setDispatchLoading(false);
      setDispatchStep(0);
      showToast("Exercise request failed. No broadcast was sent.");
    }
  };

  const handleGenerateBriefing = async (lang = briefingLanguage) => {
    if (!scenarioMode) return;
    setBriefingData(null);
    setBriefingModalOpen(true);
    setBriefingLoading(true);
    try {
      const stormPayload = {
        name: system?.name || "Cyclone System",
        category: displayCategory,
        intensity_knots: knots,
        wind_kmh: kmh,
        surge_m: surgeCalcData?.peak_surge_height_m || surgeM,
        basin: system?.basin || "Bay of Bengal"
      };
      const data = await apiFetch<{briefing: Briefing}>("/api/ai/pre-landfall-briefing", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ mode: "SCENARIO", storm_data: stormPayload, language: lang })
      });
      setBriefingData(data.briefing);
    } catch (err) {
      console.error("Failed to generate briefing", err);
    } finally {
      setBriefingLoading(false);
    }
  };

  const handleCopyText = (txt: string) => {
    navigator.clipboard.writeText(txt);
    showToast("Copied to clipboard!");
  };

  // Filtered Substations with IVF Scores
  const analyzedSubstations = POWER_SUBSTATIONS.map(sub => ({
    ...sub,
    ivf: calculateSubstationVulnerability(sub, simWindKts, surgeCalcData?.peak_surge_height_m ?? surgeM ?? undefined, simRainMm)
  }));

  const filteredSubstations = analyzedSubstations.filter(sub => {
    const matchesCriticality = infraFilter === "all" ||
      (infraFilter === "critical" && sub.ivf.riskCategory === "CRITICAL") ||
      (infraFilter === "high" && (sub.ivf.riskCategory === "CRITICAL" || sub.ivf.riskCategory === "HIGH"));
    const matchesRegion = regionFilter === "ALL" || sub.region.toLowerCase().includes(regionFilter.toLowerCase());
    const matchesSearch = !searchFilter || sub.name.toLowerCase().includes(searchFilter.toLowerCase()) || sub.type.toLowerCase().includes(searchFilter.toLowerCase());
    return matchesCriticality && matchesRegion && matchesSearch;
  });

  // Filtered Routes with Vulnerability
  const analyzedRoutes = EVACUATION_ROUTES.map(r => ({
    ...r,
    vuln: calculateRouteVulnerability(r, simWindKts, surgeCalcData?.peak_surge_height_m ?? surgeM ?? undefined, simRainMm)
  }));

  // Filtered Shelters with Suitability
  const analyzedShelters = MEDICAL_SHELTERS.map(s => ({
    ...s,
    suitability: calculateShelterSuitability(s, simWindKts)
  }));

  const filteredShelters = analyzedShelters.filter(shl => {
    const matchesRegion = regionFilter === "ALL" || shl.region.toLowerCase().includes(regionFilter.toLowerCase());
    const matchesSearch = !searchFilter || shl.name.toLowerCase().includes(searchFilter.toLowerCase()) || shl.type.toLowerCase().includes(searchFilter.toLowerCase());
    return matchesRegion && matchesSearch;
  });

  const totalShelterCapacity = MEDICAL_SHELTERS.reduce((acc, s) => acc + s.capacityPersons, 0);
  const totalMedicalBeds = MEDICAL_SHELTERS.reduce((acc, s) => acc + s.medicalBeds, 0);
  const totalGridCapacity = POWER_SUBSTATIONS.reduce((acc, s) => acc + s.capacityMVA, 0);
  const criticalSubstationsCount = analyzedSubstations.filter(s => s.ivf.riskCategory === "CRITICAL").length;

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-full min-h-[500px] gap-4">
        <div className="w-10 h-10 rounded-full border-3 border-primary/20 border-t-primary animate-spin" />
        <p className="text-sm font-medium text-muted-foreground animate-pulse">Loading coastal infrastructure and resilience telemetry...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 animate-in fade-in duration-500 pb-12 w-full">
      <div className="glass-card p-4 border-border" role="status">
        <p>{scenarioMode ? "ILLUSTRATIVE SCENARIO — asset names, coordinates, capacities and risk calculations are unverified examples." : "Operational status not verified. No authorized infrastructure observations are connected."}</p>
        {system && <p>Source: {system.source ?? "Unavailable"} · Observation: {system.observation_time_utc ?? "Unavailable"} · {system.is_stale ? "STALE" : "Check source freshness"}</p>}
        <label><input type="checkbox" checked={scenarioMode} onChange={e => setScenarioMode(e.target.checked)} /> Show illustrative scenario assets</label>
      </div>
      {/* ── Top Header Bar ─────────────────────────────────────────────────── */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 glass-card p-6 border-border/80 relative overflow-hidden">
        <div className="absolute -right-20 -top-20 w-64 h-64 bg-amber-500/10 rounded-full blur-3xl pointer-events-none" />

        <div className="space-y-1.5 z-10">
          <div className="flex flex-wrap items-center gap-2.5">
            <span className="flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider bg-amber-500/15 text-amber-400 border border-amber-500/30">
              <Building2 className="w-3.5 h-3.5" />
              Critical Infrastructure & Vulnerability Forecaster
            </span>
            <span className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider border ${sourceBadge.badgeClass}`}>
              {sourceBadge.shortLabel}
            </span>
            {system && (
              <span className="text-xs text-muted-foreground font-mono">
                {system.provenance ?? "UNKNOWN"}: {system.name} ({displayCategory} • {rawKnots ?? "Unavailable"} KT)
              </span>
            )}
          </div>
          <h1 className="text-2xl sm:text-3xl font-heading font-black text-foreground tracking-tight">
            Infrastructure observations & explicit scenarios
          </h1>
          <p className="text-sm text-muted-foreground max-w-4xl">
            Inspect unavailable field observations or opt into illustrative infrastructure and surge scenarios. Exercise communications remain local drafts.
          </p>

          {/* Field Operational Verification Advisory (#50 & #51) */}
          <div className="mt-3 p-3 px-4 rounded-xl bg-amber-500/10 border border-amber-500/25 flex items-start gap-3 text-xs text-amber-200">
            <ShieldAlert className="w-4 h-4 text-amber-400 shrink-0 mt-0.5" />
            <div>
              <span className="font-bold text-amber-400 uppercase tracking-wide text-[10px] block mb-0.5">Field Operational Verification Advisory</span>
              <p className="text-muted-foreground leading-relaxed">
                Example asset names, locations and capacities have no verified source inventory. Current operational attributes remain unavailable until authorized field observations are supplied.
              </p>
            </div>
          </div>
        </div>

        {/* Storm Selector & AI Briefing Actions */}
        <div className="flex items-center gap-2.5 z-10 shrink-0 flex-wrap">
          <select
            aria-label="Selected cyclone"
            value={selectedCycloneId || system?.id}
            onChange={(e) => {
              const storm = cyclonesList.find(s => s.id === e.target.value);
              selectCyclone(e.target.value, storm?.name);
            }}
            className="px-3 py-2 bg-secondary/80 hover:bg-secondary border border-border rounded-lg text-xs font-semibold text-foreground focus:outline-none focus:ring-1 focus:ring-primary cursor-pointer transition-colors shadow-xs"
          >
            {cyclonesList.map((s) => (
              <option key={s.id} value={s.id}>
                {s.name} {s.category ? `(${s.category})` : ""}
              </option>
            ))}
          </select>

          <button
            onClick={() => handleGenerateBriefing(briefingLanguage)}
            className="px-3.5 py-2 rounded-lg bg-primary text-primary-foreground hover:bg-primary/90 text-xs font-bold transition-all flex items-center gap-1.5 shadow-md shadow-primary/20 cursor-pointer"
          >
            <Sparkles className="w-3.5 h-3.5 animate-pulse" />
            <span>Scenario summary</span>
          </button>

          <button
            onClick={() => setActiveTab("dispatch")}
            className="px-3.5 py-2 rounded-lg bg-red-500/20 hover:bg-red-500/30 border border-red-500/40 text-red-300 text-xs font-bold transition-all flex items-center gap-1.5 cursor-pointer shadow-md"
          >
            <Siren className="w-3.5 h-3.5 text-red-400" />
            <span>Exercise drafts</span>
          </button>
        </div>
      </div>

      {/* Toast Notification */}
      {toast && (
        <div className="fixed bottom-6 right-6 bg-zinc-900 text-white border border-primary/40 px-4 py-3 rounded-xl shadow-2xl shadow-primary/20 animate-in slide-in-from-bottom-3 z-50 flex items-center gap-2.5 text-sm font-medium">
          <CheckCircle2 className="w-4 h-4 text-primary shrink-0" />
          {toast}
        </div>
      )}

      {/* ── Metric Summary Tiles ───────────────────────────────────────────── */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="glass-card p-5 border-border space-y-2">
          <div className="flex items-center justify-between">
            <span className="p-2.5 rounded-xl bg-amber-500/10 text-amber-400 border border-amber-500/20">
              <Zap className="w-5 h-5" />
            </span>
            <span className="text-xs font-mono font-bold text-red-400 bg-red-500/10 px-2 py-0.5 rounded">
              {scenarioMode ? `${criticalSubstationsCount} scenario nodes` : "Unverified inventory"}
            </span>
          </div>
          <p className="text-xs text-muted-foreground font-medium">Power Transmission Grid IVF</p>
          <p className="text-2xl font-mono font-black text-foreground">{scenarioMode ? `${(totalGridCapacity / 1000).toFixed(1)}k (assumed)` : "Unavailable"} <span className="text-xs font-normal text-muted-foreground">MVA Capacity</span></p>
          <p className="text-[11px] text-amber-400 font-semibold">Multi-factor: Flood (30%) + Wind (25%) + Elev (15%)</p>
        </div>

        <div className="glass-card p-5 border-border space-y-2">
          <div className="flex items-center justify-between">
            <span className="p-2.5 rounded-xl bg-blue-500/10 text-blue-400 border border-blue-500/20">
              <Waves className="w-5 h-5" />
            </span>
            <span className="text-xs font-mono font-bold text-blue-400 bg-blue-500/10 px-2 py-0.5 rounded">Hydrodynamic</span>
          </div>
          <p className="text-xs text-muted-foreground font-medium">Peak Storm Surge Height</p>
          <p className="text-2xl font-mono font-black text-foreground">
            {surgeM ?? "Unavailable"} <span className="text-xs font-normal text-muted-foreground">meters AMSL</span>
          </p>
          <p className="text-[11px] text-cyan-400 font-semibold">
            Inland Penetration: {surgeCalcData?.inland_penetration_km ?? "Unavailable"} km
          </p>
        </div>

        <div className="glass-card p-5 border-border space-y-2">
          <div className="flex items-center justify-between">
