              POWER_SUBSTATIONS.map((sub, i) => (
                <CircleMarker
                  key={`sub-${i}`}
                  center={[sub.lat, sub.lon]}
                  radius={7}
                  fillColor="#f59e0b"
                  color="#ffffff"
                  weight={2}
                  fillOpacity={0.95}
                >
                  <Popup>
                    <div className="p-1.5 space-y-1.5 text-xs text-white">
                      <div className="flex items-center gap-1.5 text-amber-400 font-bold text-sm">
                        <Zap className="w-4 h-4 shrink-0" />
                        <span>{sub.name}</span>
                      </div>
                      <p className="text-zinc-300 text-[11px]">Type: <strong className="text-white">{sub.type}</strong></p>
                      <p className="text-zinc-300 text-[11px]">Assumed capacity: <strong className="text-white">{sub.capacityMVA} MVA</strong></p>
                      <p className="text-zinc-300 text-[11px]">Coastal Distance: <strong className="text-white">{sub.coastalDistanceKm} km</strong> (Elev: {sub.elevationMeters}m)</p>
                      <span className="inline-block px-2.5 py-1 mt-1 rounded-md text-[10.5px] font-bold bg-amber-500/20 text-amber-300 border border-amber-500/40">
                        Criticality: {sub.criticality}
                      </span>
                    </div>
                  </Popup>
                  <Tooltip direction="top" offset={[0, -6]}>
                    <span className="text-[9.5px] font-bold font-mono text-amber-200 bg-zinc-950/90 px-1 py-0.5 rounded border border-amber-500/30">
                      ⚡ {sub.name.split(" ")[0]} ({sub.capacityMVA}MVA)
                    </span>
                  </Tooltip>
                </CircleMarker>
              ))
            )}

            {/* 4. Cyclone Shelters & Trauma Hospitals */}
            {(infraFilter === 'all' || infraFilter === 'shelters') && (
              MEDICAL_SHELTERS.map((shl, i) => (
                <CircleMarker
                  key={`shl-${i}`}
                  center={[shl.lat, shl.lon]}
                  radius={7}
                  fillColor="#10b981"
                  color="#ffffff"
                  weight={2}
                  fillOpacity={0.95}
                >
                  <Popup>
                    <div className="p-1.5 space-y-1.5 text-xs text-white">
                      <div className="flex items-center gap-1.5 text-emerald-400 font-bold text-sm">
                        <Building2 className="w-4 h-4 shrink-0" />
                        <span>{shl.name}</span>
                      </div>
                      <p className="text-zinc-300 text-[11px]">Type: <strong className="text-white">{shl.type}</strong></p>
                      <p className="text-zinc-300 text-[11px]">Assumed capacity: <strong className="text-white">{shl.capacityPersons.toLocaleString()} persons</strong></p>
                      <p className="text-zinc-300 text-[11px]">Assumed beds: <strong className="text-white">{shl.medicalBeds} Beds</strong></p>
                      <p className="text-zinc-300 text-[10.5px]">Backup Power: <strong className="text-white">{"Unavailable"}</strong></p>
                      <span className="inline-block px-2.5 py-1 mt-1 rounded-md text-[10.5px] font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-500/40">
                        Status: {"Operational status not verified"}
                      </span>
                    </div>
                  </Popup>
                  <Tooltip direction="top" offset={[0, -6]}>
                    <span className="text-[9.5px] font-bold font-mono text-emerald-200 bg-zinc-950/90 px-1 py-0.5 rounded border border-emerald-500/30">
                      🏥 {shl.name.split(" ")[0]} ({shl.capacityPersons}p)
                    </span>
                  </Tooltip>
                </CircleMarker>
              ))
            )}
          </>
        )}

        {/* ── Tropical Cyclone Best-Track Geometry ─────────────────────────── */}
        {activeSystem && (
          <>
            {/* 2. Track Segments Colored by Severity */}
            {points.map((pt, idx) => {
              if (idx === 0) return null;
              const prevPt = points[idx - 1];
              const color = getIntensityColor(pt.intensity_knots);
              
              return (
                <Polyline 
                  key={`seg-${idx}`} 
                  positions={[[prevPt.lat, prevPt.lon], [pt.lat, pt.lon]]} 
                  pathOptions={{
                    color: color,
                    weight: 3.5,
                    dashArray: pt.is_forecast ? "6, 6" : undefined,
                    opacity: 0.95
                  }}
                />
              );
            })}

            {/* 3. Track Point Markers Colored by Actual Severity */}
            {points.map((pt, idx) => {
              const label = getPointLabel(pt);
              const color = getIntensityColor(pt.intensity_knots);
              const isLandfallPt = pt.is_landfall || (pt.label && pt.label.toLowerCase().includes("landfall"));

              return (
                <React.Fragment key={`pt-group-${idx}`}>
                  <CircleMarker 
                    center={[pt.lat, pt.lon]} 
                    radius={isLandfallPt ? 8 : (pt.is_forecast ? 5.5 : 5)} 
                    fillColor={isLandfallPt ? "#dc2626" : color} 
                    color="#ffffff" 
                    weight={isLandfallPt ? 3 : 1.5} 
                    fillOpacity={1}
                  >
                    {showLabels && (
                      <Tooltip 
                        permanent
                        direction="right" 
                        offset={[10, 0]} 
                        className="imd-bullet-label"
                      >
                        <div className={`font-mono text-[10px] font-bold whitespace-nowrap px-2 py-0.5 rounded-md backdrop-blur-md transition-all shadow-md ${
                          isLandfallPt 
                            ? "bg-red-950/95 text-red-100 border border-red-500/80 shadow-red-950/40 flex items-center gap-1"
                            : pt.is_forecast 
                              ? "bg-zinc-950/90 text-red-300 border border-red-500/35" 
                              : "bg-zinc-950/90 text-zinc-200 border border-zinc-700/60"
                        }`}>
                          {isLandfallPt && <span className="w-1.5 h-1.5 rounded-full bg-red-400 animate-pulse shrink-0" />}
                          <span>{isLandfallPt ? `🎯 ${label}` : label}</span>
                        </div>
                      </Tooltip>
                    )}
                    <Popup>
                      <div className="p-1 space-y-1 text-xs">
                        <p className="font-bold text-foreground">{pt.category}</p>
                        <p className="text-muted-foreground">Wind: <strong className="text-foreground">{pt.intensity_knots ?? "Not available"} KT ({(pt.intensity_knots == null ? null : Math.round(pt.intensity_knots * 1.852))} km/h)</strong></p>
                        <p className="text-muted-foreground">Fix: {pt.lat.toFixed(1)}°N, {pt.lon.toFixed(1)}°E</p>
                        {isLandfallPt && (
                          <p className="font-bold text-red-500 bg-red-500/10 p-1 rounded border border-red-500/20">
                            🎯 Landfall Coastal Crossing Fix
                          </p>
                        )}
                      </div>
                    </Popup>
                  </CircleMarker>
                </React.Fragment>
              );
            })}
          </>
        )}
      </MapContainer>
    </div>
  );
}

"use client";
import { useRouter } from "next/navigation";

import React from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { Activity, UploadCloud, History, FileText, Settings, Wind, LogOut, GitCompare, Building2 } from "lucide-react";
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
import { CycloneLogo } from "@/components/CycloneLogo";

import { useUser, useClerk } from "@clerk/nextjs";

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { useLanguage } from "@/context/LanguageContext";

export const navItems = [
  { key: "live_monitoring", name: "Live Monitoring", href: "/dashboard", icon: Activity },
  { key: "classification", name: "Classification", href: "/classification", icon: UploadCloud },
  { key: "historical_archive", name: "Historical Archive", href: "/archive", icon: History },
  { key: "storm_comparison", name: "Storm Comparison", href: "/compare", icon: GitCompare },
  { key: "track_forecast", name: "Track Forecast", href: "/forecast", icon: Wind },
  { key: "alerts_reports", name: "Alerts & Reports", href: "/reports", icon: FileText },
  { key: "infrastructure_relief", name: "Infrastructure & Relief", href: "/infrastructure", icon: Building2 },
  { key: "settings", name: "Settings", href: "/settings", icon: Settings },
];

export function Sidebar() {
  const router = useRouter();
  const pathname = usePathname();
  const { user: clerkUser, isLoaded } = useUser();
  const { signOut } = useClerk();
  const { t } = useLanguage();

  const isAuthenticated = Boolean(isLoaded && clerkUser);
  const displayName = isAuthenticated
    ? (clerkUser?.fullName || clerkUser?.primaryEmailAddress?.emailAddress?.split("@")[0] || "Officer")
    : "Guest Visitor";
  const displayRole = isAuthenticated ? "SIGNED IN" : "PUBLIC VIEWER";
  const displayInitials = isAuthenticated ? displayName.slice(0, 2).toUpperCase() : "GV";
  const avatarUrl = isAuthenticated ? clerkUser?.imageUrl : null;

  const handleLogout = async () => {
    if (typeof window !== "undefined") {
      localStorage.removeItem("cyclonet_user");
      localStorage.removeItem("cyclonet_auth_token");
      if (clerkUser) {
        await signOut({ redirectUrl: "/" });
      } else {
        router.push("/");
      }
    }
  };

  return (
    <aside className="w-64 hidden lg:flex flex-col h-screen fixed left-0 top-0 sidebar-mesh border-r border-border">
      <div className="p-6 flex items-center justify-between">
        <Link href="/dashboard" className="flex items-center gap-3 group">
          <div className="relative flex items-center justify-center group-hover:scale-105 transition-transform">
            <CycloneLogo size={32} />
          </div>
          <span className="font-heading font-extrabold text-xl bg-gradient-to-r from-blue-400 via-sky-300 to-indigo-400 bg-clip-text text-transparent tracking-tight">
            CycloNet
          </span>
        </Link>
      </div>

      <nav className="flex-1 px-4 py-2 space-y-1 overflow-y-auto scrollbar-hide">
        {navItems.map((item) => {
          const isActive = pathname === item.href;
          const Icon = item.icon;
          const translatedName = t(item.key) || item.name;
          return (
            <Link
              key={item.name}
              href={item.href}
              className={cn(
                "flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all duration-200 group relative overflow-hidden",
                isActive
                  ? "text-slate-900 dark:text-white bg-slate-900/10 dark:bg-white/10 shadow-xs font-semibold"
                  : "text-slate-600 dark:text-zinc-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-900/5 dark:hover:bg-white/5"
              )}
            >
              {isActive && (
                <div className="absolute inset-0 bg-slate-900/[0.08] dark:bg-white/[0.08] rounded-lg -z-10" />
              )}
              {isActive && (
                <div className="absolute left-0 top-1/2 -translate-y-1/2 w-1 h-5 bg-slate-900 dark:bg-white rounded-r-full" />
              )}
              <Icon className={cn("w-5 h-5 transition-colors", isActive ? "text-slate-900 dark:text-white" : "text-slate-500 group-hover:text-slate-900 dark:text-zinc-400 dark:group-hover:text-white")} />
              <span>{translatedName}</span>
            </Link>
          );
        })}
      </nav>

      {/* Officer Profile & Logout Bottom Bar (directs to auth/login) */}
      <div className="p-3 border-t border-border mt-auto">
        <div className="flex items-center justify-between p-2 rounded-xl bg-slate-900/[0.03] dark:bg-white/[0.03] hover:bg-slate-900/[0.06] dark:hover:bg-white/[0.06] transition-colors">
          <div className="flex items-center gap-3 min-w-0">
            {avatarUrl ? (
              <img
                src={avatarUrl}
                alt={displayName}
                className="w-9 h-9 rounded-full object-cover shadow-xs shrink-0 ring-2 ring-indigo-500/20"
              />
            ) : (
              <div className="w-9 h-9 rounded-full bg-gradient-to-tr from-indigo-600 to-violet-500 text-white font-bold text-xs flex items-center justify-center shadow-xs shrink-0 ring-2 ring-indigo-500/20">
                {displayInitials}
              </div>
            )}
            <div className="flex flex-col min-w-0">
              <span className="text-xs sm:text-sm font-bold text-slate-900 dark:text-white truncate leading-tight">
                {displayName}
              </span>
              <span className="text-[10px] font-semibold text-slate-500 dark:text-zinc-400 uppercase tracking-wider truncate mt-0.5">
                {displayRole}
              </span>
            </div>
          </div>

          <div className="flex items-center gap-1 shrink-0 ml-2">
            <Link
              href="/settings"
              className="p-1.5 rounded-lg text-slate-500 hover:text-slate-900 dark:text-zinc-400 dark:hover:text-white hover:bg-slate-900/10 dark:hover:bg-white/10 transition-colors"
              title="Settings"
              aria-label="Settings"
            >
              <Settings className="w-4 h-4" />
            </Link>
            
            <button
              onClick={handleLogout}
              className="p-1.5 rounded-lg text-slate-500 hover:text-rose-600 dark:text-zinc-400 dark:hover:text-rose-400 hover:bg-rose-500/10 transition-colors cursor-pointer"
              title="Sign Out to Landing Page"
              aria-label="Sign Out to Landing Page"
            >
              <LogOut className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </aside>
  );
}

